#!/usr/bin/env bash
# the step-6C proof: pristine cache-off rebuild at the work path, R5 against the 632b35459 objects, the include-order record, the fan-in arms, style, the eight smokes, the gates and scripts that compile against src, make parsers-sc in both trees, the row's DONE-WHEN
S4=/tmp/claude-1000/-home-claude-cto/b1caac4c-9b75-4393-9260-1c72f906f86b/scratchpad; SO=/tmp/claude-1000/-home-claude-cto/25cbd82c-ea4e-46bc-9ee6-3c52fc5dcc1f/scratchpad; W=$SO/hdr/SCRIP; H=$SO/hdr/harness/scripts; R=/home/claude_cto/SCRIP; cd $W || exit 2
echo "== 0 pristine  $(date +%T)"; CCACHE_DISABLE=1 S4E_NO_BUILD_CACHE=1 make -j8 pristine > $S4/c-pristine.log 2>&1; echo "pristine rc=$? compiles=$(grep -c -- ' -c ' $S4/c-pristine.log) errors=$(grep -c ' error' $S4/c-pristine.log)"
echo "== 1 R5"; WO=/tmp/si_objs$(printf %s "$W" | tr / -)
bash $H/util_objects_identical_stripped.sh --no-comdat $S4/parent-objs-6c/obj $WO $S4/parent-objs-6c/out $W/out > $S4/r5-6c.log 2>&1; echo "R5 rc=$? :: $(grep '^objects=' $S4/r5-6c.log | cut -c1-300)"; grep -E '^(DIFF|ONLY)' $S4/r5-6c.log | head -12 | cut -c1-220
echo "== 2 order"; python3 -I $S4/hdr_order.py --root $W --cmds $S4/make-n-6c.txt --out $S4/order-child-6c.json 2>&1 | tail -1; python3 -I $S4/order_cmp.py $S4/order-parent-6c.json $S4/order-child-6c.json $R/src $W/src 2>&1 | tail -4
echo "== 3 fan-in arms"; python3 -I $H/util_header_fanin.py --root $W --ratchet all 2>/dev/null | grep -E 'RAISED|^arm' | cut -c1-140; python3 -I $H/util_header_fanin.py --root $W --bare 2>/dev/null | tail -1; python3 -I $H/util_header_fanin.py --root $W --unused 2>/dev/null | tail -1; python3 -I $H/util_header_fanin.py --root $W --ceiling 2>/dev/null | tail -1
echo "== 4 style (hand-written files only; the generated parsers are regenerated, never edited)"; files=$(git diff --name-only HEAD -- src | grep -vE '\.(tab\.[ch]|lex\.c)$|lex\.rebus\.c|\.y$|\.l$' | while read f; do [ -f "$f" ] && echo "$f"; done); echo "$(echo "$files" | wc -l) files"; python3 ../harness/scripts/util_reflow_200.py --check $files 2>&1 | tail -1 | cut -c1-160; python3 ../harness/scripts/strip_comments.py --check $files 2>&1 | tail -1 | cut -c1-160
echo "== 5 the flag library and the retired-directory gate"; ( . $H/lib_build_flags.sh && build_flags_load $W && echo "BF_RT_INCS=$BF_RT_INCS" ) 2>&1 | tail -1 | cut -c1-160; S4E_DONE_WHEN_RUN=1 bash $H/test_gate_no_script_passes_a_retired_include_directory.sh 2>&1 | tail -1 | cut -c1-120
echo "== 6 smokes  $(date +%T)"; for l in snobol4 snocone rebus icon prolog pascal raku scrip_all_modes; do S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash ../harness/scripts/test_smoke_$l.sh > $S4/smoke6c-$l.log 2>&1; echo "SMOKE $l rc=$?"; done
echo "== 7 gates and scripts that compile against src  $(date +%T)"; for g in test_gate_no_header_reaches_more_units_than_its_users.sh test_gate_ct_grow_grows_in_place_at_the_frontier_or_allocs_copies_and_abandons.sh test_unit_rt_arena.sh test_gate_coexpr_stack_of_uncreated_thread.sh test_gate_shared_builtin_id_table_is_self_consistent.sh test_gate_rtx_entries_keep_the_rtcc_four.sh test_gate_rtx_every_leaf_carries_cfi_true_at_every_pc.sh test_gate_mint_op_is_one_numbering.sh test_gate_stage2_isolation.sh test_gate_planner_objects_leave_no_emitter_symbol_undefined.sh test_gate_core_fn_table_is_current.sh test_gate_box_cell_shapes_inc_is_current.sh test_gate_pl_meta_specs_inc_is_current.sh; do t0=$(date +%s); S4E_DONE_WHEN_RUN=1 timeout -k 5 1800 bash $H/$g > $S4/gate6c-$g.log 2>&1; echo "GATE $g rc=$? $(( $(date +%s) - t0 ))s :: $(grep -E 'GATE (OK|PASS|FAIL|RED|GREEN|UNPROVEN)|⛔|REFUSE|summary|PASS|FAIL' $S4/gate6c-$g.log | tail -1 | cut -c1-110)"; done
grep -E '^  (RED|ok|FAIL) +ARM' $S4/gate6c-test_gate_no_header_reaches_more_units_than_its_users.sh.log | cut -c1-100
echo "== 8 parsers-sc in both trees  $(date +%T)"; (cd $R && make parsers-sc > $S4/psc-root.log 2>&1; echo "root parsers-sc rc=$?"); make parsers-sc > $S4/psc-work.log 2>&1; echo "work parsers-sc rc=$?"; for f in $(cd $W/out && ls *.o sc_mod*/*.o 2>/dev/null | head -40); do cmp -s $R/out/$f $W/out/$f && echo "same $f" || echo "DIFF $f"; done | sort | uniq -c | sort -rn | head -5
echo "== 9 the row's DONE-WHEN"; sed -n 's/^DONE-WHEN: //p' /home/resources/postoffice/tasks/headers-step-6-the-layers-*.task.md > $S4/dw6.sh; S4E_HOME=$SO/hdr bash $S4/dw6.sh 2>&1 | tail -2 | cut -c1-200; echo "dw6 rc=${PIPESTATUS[0]}"
echo "6C PROOF DONE $(date +%T)"
